function bindExternal(){document.querySelectorAll('[data-external]').forEach(function(b){b.onclick=function(){var url=Core.fillTemplate(b.dataset.url,S.ctx);try{var hist=JSON.parse(localStorage.getItem('rw_partner_clicks')||'[]');hist.unshift({provider:b.dataset.external,category:S.cat,destination:S.ctx.destination,at:now()});localStorage.setItem('rw_partner_clicks',JSON.stringify(hist.slice(0,100)))}catch(e){}if(url)window.open(url,'_blank','noopener,noreferrer')}})}
function openDirectBooking(x,isDemo){var ns=Core.nights(S.ctx.checkin,S.ctx.checkout),amount=Number(x.price||0)*ns,pct=Number(x.commissionPct||S.travel.stayCommissionPct||7);$('modalbox').innerHTML='<div class="modalhead"><div><h2>'+esc(x.name)+'</h2><div class="muted">'+esc(x.room)+' · '+ns+' night'+(ns>1?'s':'')+'</div></div><button class="x" onclick="RWClose()">×</button></div><div class="stats"><div class="stat"><b>'+money(x.price)+'</b><span>Per night</span></div><div class="stat"><b>'+ns+'</b><span>Nights</span></div><div class="stat"><b>'+S.ctx.guests+'</b><span>Guests</span></div><div class="stat"><b>'+money(amount)+'</b><span>Total</span></div></div><div class="fields"><div class="field"><label>Your name</label><input id="bgname" placeholder="Traveller name"></div><div class="field"><label>Email</label><input id="bgemail" type="email" value="'+esc(S.user&&S.user.email||'')+'" placeholder="you@example.com"></div><div class="field"><label>Phone</label><input id="bgphone" placeholder="+91…"></div><div class="field"><label>Note</label><input id="bgnote" placeholder="Arrival time or a question"></div></div><div class="notice"><b>No payment is taken here.</b> The property receives your request and confirms availability.</div><div class="actions"><button class="btn" id="sendBooking">Send booking request</button><button class="btn secondary" onclick="RWClose()">Cancel</button></div>'; $('modal').classList.add('open');$('sendBooking').onclick=async function(){var name=$('bgname').value.trim(),email=$('bgemail').value.trim();if(!name||!email){alert('Add your name and email.');return}var rec={ref:Core.bookingRef(),status:'requested',partnerUid:x.partnerUid,guestUid:S.user&&S.user.uid||'demo_guest',guestName:name,guestEmail:email,guestPhone:$('bgphone').value.trim(),note:$('bgnote').value.trim(),property:x.name,room:x.room,roomId:x.roomId||'',zone:x.zone||'',area:x.area||'',checkIn:S.ctx.checkin,checkOut:S.ctx.checkout,guests:S.ctx.guests,nights:ns,roomPrice:Number(x.price||0),amount:amount,commissionPctSnapshot:pct,at:now(),createdAt:now()};if(isDemo){var D=demo();rec._id=uid('booking');D.bookings.unshift(rec);saveDemo(D);bookingSuccess(rec.ref);return}if(!S.user){authPrompt(function(){closeModal();openDirectBooking(x,false)});return}rec.guestUid=S.user.uid;try{var doc=await db.collection('roomBookings').add(rec);rec._id=doc.id;bookingSuccess(rec.ref)}catch(e){showError('Could not send this request',friendly(e))}}}
function bookingSuccess(ref){$('modalbox').innerHTML='<div class="success"><div class="big">✓</div><h2>Request sent</h2><p class="muted">The property can now confirm or decline your request.</p><div class="code">'+esc(ref)+'</div><div><button class="btn" onclick="RWClose()">Done</button></div></div>'}
function authPrompt(after){$('modalbox').innerHTML='<div class="modalhead"><div><h2>Sign in to continue</h2><div class="muted">Use your RoamWise account or create one here.</div></div><button class="x" onclick="RWClose()">×</button></div>'+authFields('trav')+'<div class="actions"><button class="btn" id="travLogin">Sign in</button><button class="btn secondary" id="travCreate">Create account</button></div><div id="travMsg"></div>';$('modal').classList.add('open');$('travLogin').onclick=function(){doLogin('trav',after)};$('travCreate').onclick=function(){doCreate('trav',after)}}
function authFields(p){return '<div class="fields" style="margin-top:12px"><div class="field full"><label>Email</label><input id="'+p+'Email" type="email" autocomplete="email"></div><div class="field full"><label>Password</label><input id="'+p+'Pass" type="password" autocomplete="current-password"></div></div>'}
async function doLogin(p,after){if(!auth)return;var e=$(p+'Email').value.trim(),pw=$(p+'Pass').value;try{await auth.signInWithEmailAndPassword(e,pw);if(after)after()}catch(x){msg(p+'Msg',friendly(x),true)}}
async function doCreate(p,after){if(!auth)return;var e=$(p+'Email').value.trim(),pw=$(p+'Pass').value;if(pw.length<6){msg(p+'Msg','Password needs at least 6 characters.',true);return}try{await auth.createUserWithEmailAndPassword(e,pw);if(after)after()}catch(x){msg(p+'Msg',friendly(x),true)}}
function msg(id,text,bad){var e=$(id);if(e)e.innerHTML='<div class="notice '+(bad?'bad':'good')+'">'+esc(text)+'</div>'}
function friendly(e){var code=String(e&&e.code||''),s=(e&&e.message)||String(e||'Something went wrong.');if(/email-already-in-use/.test(code))return 'An account already uses this email. Sign in instead, then open Settings → Sign-in & security to add another sign-in option.';if(/account-exists-with-different-credential/.test(code))return 'This email already has a RoamWise sign-in option. Use that option first, then add another in Settings so your trips stay on one account.';if(/permission/i.test(s))return 'This account cannot do that action yet.';if(/credential/i.test(s))return 'Email or password did not match.';return 'Something went wrong. Please try again.'}
