function ownerStartCard(title,copy){return '<section class="card rw-owner-start"><span class="eyebrow">ONE PROPERTY · ONE APPLICATION · ONE MOU</span><h2>'+esc(title)+'</h2><p class="muted">'+esc(copy)+'</p><div class="rw-owner-start-steps"><span><b>1</b> Property basics</span><span><b>2</b> Accept V4 MOU</span><span><b>3</b> RoamWise review</span></div><div class="actions"><a class="btn" href="/partner/join/">Start the 3-minute application →</a><a class="btn secondary" href="/creators/match.html?role=property">Match with verified creators</a></div><p class="rw-market-fine">Applying is free. Nothing goes live and no guest payment is taken until verification and booking-flow checks are complete.</p></section>'}
