  var ref=db.collection('config').doc('partners'),c=await ref.get(),list=c.exists&&Array.isArray((c.data()||{}).list)?c.data().list.slice():[],pid='p_'+detSlug(p.name);
  list=list.filter(function(x){return x&&x.id!==pid});
