    if(p.hook)e.hook=String(p.hook).slice(0,300);['advancePct','freeCancelHours','lateRefundPct'].forEach(function(k){var n=Math.round(Number(p[k]));if(isFinite(n)&&n>0)e[k]=n});var pc=Math.round(Number(p.photoCount));if(pc>0)e.photoCount=Math.min(4,pc);if(p.mapsUrl&&detUrlOk('mapsUrl',p.mapsUrl))e.mapsUrl=p.mapsUrl;
